begin;
insert into public.studios(slug,name,about,highlight,web,founded,base,founders,verified) values ('fictiorama-studios','Fictiorama Studios','Estudio independiente de narrativa, fundado por tres hermanos. Creador de Dead Synchronicity (2015), Do Not Feed the Monkeys (2018), The Fabulous Fear Machine y Do Not Feed the Monkeys 2099 (2023).','Do Not Feed the Monkeys fue nominado a tres premios IGF Awards.','https://fictiorama.itch.io','2012','Madrid (España)','Mario, Alberto y Luis Oliván',true) on conflict (slug) do nothing;
insert into public.studios(slug,name,about,highlight,web,founded,base,founders,verified) values ('remulla-games','Remulla Games','Estudio independiente en español. Speed Bubble ganó «Mejor arte» y «Mejor adaptación al tema» en la Valencia Game Jam 25.',null,'https://remullagames.com',null,null,null,true) on conflict (slug) do nothing;
insert into public.products(id,studio_id,title,description,genre,platform,pegi,adult,price_pz,discount_pct,trial,itch_url,store_url,embed_url,exe_match,status) select 'monkeys',s.id,'Do Not Feed the Monkeys 2099','Simulador de voyeur digital ambientado en 2099.','Simulación','Steam',null,true,1290,0,false,null,'https://store.steampowered.com/app/1964040/Do_Not_Feed_the_Monkeys_2099/',null,null,'published' from public.studios s where s.name='Fictiorama Studios' on conflict (id) do nothing;
insert into public.products(id,studio_id,title,description,genre,platform,pegi,adult,price_pz,discount_pct,trial,itch_url,store_url,embed_url,exe_match,status) select 'fabulous',s.id,'The Fabulous Fear Machine','Estrategia narrativa de horror pulp: crea leyendas que se extienden por el mundo.','Estrategia','Steam',null,false,1550,0,false,null,'https://store.steampowered.com/app/1540350/The_Fabulous_Fear_Machine/',null,null,'published' from public.studios s where s.name='Fictiorama Studios' on conflict (id) do nothing;
insert into public.products(id,studio_id,title,description,genre,platform,pegi,adult,price_pz,discount_pct,trial,itch_url,store_url,embed_url,exe_match,status) select 'speedbubble',s.id,'Speed Bubble','Pega los bocadillos de un manga a contrarreloj.','Casual','Navegador (HTML5)',null,false,0,0,true,'https://remullagames.itch.io/speed-bubble',null,'https://html-classic.itch.zone/html/13182817/BuildWeb/index.html?v=1782666847',null,'published' from public.studios s where s.name='Remulla Games' on conflict (id) do nothing;
insert into public.products(id,studio_id,title,description,genre,platform,pegi,adult,price_pz,discount_pct,trial,itch_url,store_url,embed_url,exe_match,status) select 'maskot',s.id,'Did Someone Call a Maskot?','Juego de Remulla Games para probar en el navegador.','Por confirmar','Navegador (HTML5)',null,false,0,0,true,'https://remullagames.itch.io/did-someone-call-a-maskot',null,'https://html-classic.itch.zone/html/18307376/index.html?v=1783885022','maskot','published' from public.studios s where s.name='Remulla Games' on conflict (id) do nothing;
